-- auth_indexes (WP-12; database-29, 02-database 7.1.1): Better Auth's tables keep their columns and gain the indexes
-- and checks of the spec: one account per email whatever its case, one identity per provider account, one password per
-- user, the unverified-account purge's index and the session read index. Generated by drizzle-kit; the checks were
-- made NOT VALID by hand (rows written before them are checked by the pre-check in owner-actions/WP-12.md). These
-- tables stay far below 100,000 rows, so the indexes build in the transaction.
CREATE UNIQUE INDEX "account_provider_account_uq" ON "account" USING btree ("provider_id","account_id");--> statement-breakpoint
CREATE UNIQUE INDEX "account_one_credential_uq" ON "account" USING btree ("user_id") WHERE provider_id = 'credential';--> statement-breakpoint
CREATE INDEX "session_user_updated_idx" ON "session" USING btree ("user_id","updated_at" DESC NULLS LAST);--> statement-breakpoint
CREATE UNIQUE INDEX "user_email_lower_uq" ON "user" USING btree (lower("email"));--> statement-breakpoint
CREATE INDEX "user_unverified_created_idx" ON "user" USING btree ("created_at") WHERE NOT "user"."email_verified";--> statement-breakpoint
ALTER TABLE "account" ADD CONSTRAINT "account_credential_password_ck" CHECK (provider_id <> 'credential' OR password IS NOT NULL) NOT VALID;--> statement-breakpoint
ALTER TABLE "session" ADD CONSTRAINT "session_expiry_ck" CHECK (expires_at > created_at) NOT VALID;--> statement-breakpoint
ALTER TABLE "user" ADD CONSTRAINT "user_email_len_ck" CHECK (char_length(email) BETWEEN 3 AND 254) NOT VALID;--> statement-breakpoint
ALTER TABLE "user" ADD CONSTRAINT "user_name_len_ck" CHECK (char_length(name) <= 200) NOT VALID;
